import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Create the badge capsule plane
  const geometry = new THREE.PlaneGeometry(0.8, 0.3);
  const material = new MeshBasicNodeMaterial({
    color: 0x16161d,
    transparent: true,
    opacity: 1,
  });

  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(0, 1.6, 0);
  mesh.rotation.set(0, 0, 0);
  mesh.scale.set(1, 1, 1);

  // Load and apply the ceramic grain texture
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      material.colorNode = ctx.THREE.uv().mul(texture);
      material.needsUpdate = true;
    });
  }

  // Add accent edge light (rim light for the badge edge)
  const rimLight = new THREE.PointLight(0xff2a38, 0.8, 5);
  rimLight.position.set(0.5, 1.8, 0.8);
  mesh.add(rimLight);

  // Store timeline references for cleanup
  const timelines = [];

  // Hover interaction
  mesh.userData.handlers = {
    onPointerEnter: () => {
      // Kill any existing timeline
      timelines.forEach(t => t.kill());

      // Rise-in effect: subtle lift 0.15 units
      const tl = gsap.timeline();
      tl.to(mesh.position, {
        y: 1.75,
        duration: 0.7,
        ease: 'power3.out',
      }, 0);
      timelines.push(tl);
    },
    onPointerLeave: () => {
      // Kill any existing timeline
      timelines.forEach(t => t.kill());

      // Return to original position
      const tl = gsap.timeline();
      tl.to(mesh.position, {
        y: 1.6,
        duration: 0.7,
        ease: 'power3.out',
      }, 0);
      timelines.push(tl);
    },
    onClick: () => {
      // Press-down effect
      timelines.forEach(t => t.kill());

      const tl = gsap.timeline();
      tl.to(mesh.scale, {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: 'back.out',
      }, 0);

      // Weighted settle back
      tl.to(mesh.scale, {
        x: 1.0,
        y: 1.0,
        duration: 0.9,
        ease: 'power4.out',
      }, 0.12);

      timelines.push(tl);

      // Emit event
      ctx.emit('navigate', { to: 'hub-collection' });
    },
  };

  // Cleanup function
  mesh.userData.cleanup = () => {
    timelines.forEach(t => t.kill());
    geometry.dispose();
    material.dispose();
  };

  return mesh;
}
